13	public class JsonMerger {
14	
15	    private final JacksonMapper mapper;
16	
17	    public JsonMerger(JacksonMapper mapper) {
18	        this.mapper = Objects.requireNonNull(mapper);
19	    }
20	
21	    /**
22	     * Merges passed object with json retrieved from stored data map by id
23	     * and cast it to appropriate class. In case of any exception during merging, throws {@link InvalidRequestException}
24	     * with reason message.
25	     */
26	    public <T> T merge(T originalObject, String storedData, String id, Class<T> classToCast) {
27	        final JsonNode originJsonNode = mapper.mapper().valueToTree(originalObject);
28	        final JsonNode storedRequestJsonNode;
29	        try {
30	            storedRequestJsonNode = mapper.mapper().readTree(storedData);
31	        } catch (IOException e) {
32	            throw new InvalidRequestException(
33	                    String.format("Can't parse Json for stored request with id %s", id));
34	        }
35	        try {
36	            // Http request fields have higher priority and will override fields from stored requests
37	            // in case they have different values
38	            return mapper.mapper().treeToValue(JsonMergePatch.fromJson(originJsonNode).apply(storedRequestJsonNode),
39	                    classToCast);
40	        } catch (JsonPatchException e) {
41	            throw new InvalidRequestException(String.format(
42	                    "Couldn't create merge patch from origin object node for id %s: %s", id, e.getMessage()));
43	        } catch (JsonProcessingException e) {
44	            throw new InvalidRequestException(
45	                    String.format("Can't convert merging result for id %s: %s", id, e.getMessage()));
46	        }
47	    }
48	
49	    public <T> T merge(T originalObject, T mergingObject, Class<T> classToCast) {
50	        if (!ObjectUtils.allNotNull(originalObject, mergingObject)) {
51	            return ObjectUtils.defaultIfNull(originalObject, mergingObject);
52	        }
53	
54	        final JsonNode originJsonNode = mapper.mapper().valueToTree(originalObject);
55	        final JsonNode mergingObjectJsonNode = mapper.mapper().valueToTree(mergingObject);
56	        try {
57	            final JsonNode mergedNode = JsonMergePatch.fromJson(originJsonNode).apply(mergingObjectJsonNode);
58	            return mapper.mapper().treeToValue(mergedNode, classToCast);
59	        } catch (JsonPatchException e) {
60	            throw new InvalidRequestException(String.format(
61	                    "Couldn't create merge patch for objects with class %s", classToCast.getName()));
62	        } catch (JsonProcessingException e) {
63	            throw new InvalidRequestException(
64	                    String.format("Can't convert merging result class %s", classToCast.getName()));
65	        }
66	    }
67	
68	    /**
69	     * Returns 'toNode' with merged properties from 'fromNode'.
70	     */
71	    public JsonNode merge(JsonNode fromNode, JsonNode toNode) {
72	        try {
73	            return JsonMergePatch.fromJson(fromNode).apply(toNode);
74	        } catch (JsonPatchException e) {
75	            throw new InvalidRequestException("Couldn't create merge patch for json nodes");
76	        }
77	    }
78	}
